import Foundation
import Testing
@testable import TurboFieldfare
@testable import TurboFieldfareFormat

/// Independent metadata-only marker fixture. Sidecar and shard hashes are
/// literal entries from `scratch/qwen3.6-35b-a3b/official-995ad96eacd98c81ed38be0c5b274b04031597b0/SHA256SUMS`,
/// not values read from OfficialQwenSourceIdentity or generated by the production digest helper.
/// The expected digest was independently calculated with Python 3
/// `hashlib.sha256` over sorted UTF-8/LF-terminated canonical records:
/// c1ac463726b716e7db3a9fbe5db4cb690f95be7e5779aea02e49c2020bca7a7a.
@Suite(.serialized) struct OfficialSourceAdmissionTests {
    @Test func classifiesIndependentPinnedMetadataWithoutOpeningSourceRootOrShards() throws {
        let rootPath = IndependentOfficialSourceFixture.nonexistentSourceRoot
        #expect(!FileManager.default.fileExists(atPath: rootPath))
        let directory = try Self.writeDirectory(
            markerData: IndependentOfficialSourceFixture.markerData(sourceRoot: rootPath))
        defer { try? FileManager.default.removeItem(at: directory) }

        let admission = try ModelFamilyAdmission.classify(directoryURL: directory)
        guard case .qwenOfficialSource(let descriptor) = admission else {
            Issue.record("expected typed original-BF16 source admission")
            return
        }
        #expect(descriptor.kind == "official-safetensors-bf16-v1")
        #expect(descriptor.version == 1)
        #expect(descriptor.repository == IndependentOfficialSourceFixture.repository)
        #expect(descriptor.revision == IndependentOfficialSourceFixture.revision)
        #expect(descriptor.storageProfile == IndependentOfficialSourceFixture.storageProfile)
        #expect(descriptor.contentSHA256 == IndependentOfficialSourceFixture.expectedContentSHA256)
        #expect(descriptor.sourceRoot == rootPath)
    }

    @Test func classifiesMarkerAtExactMetadataCapAndRejectsOneByteOver() throws {
        let marker = try IndependentOfficialSourceFixture.markerData()
        let cap = Int(OfficialSourceDescriptor.maximumMarkerBytes)
        #expect(marker.count < cap)
        var exactlyAtCap = marker
        exactlyAtCap.append(contentsOf: repeatElement(UInt8(0x20), count: cap - marker.count))
        let accepted = try Self.writeDirectory(markerData: exactlyAtCap)
        defer { try? FileManager.default.removeItem(at: accepted) }
        guard case .qwenOfficialSource = try ModelFamilyAdmission.classify(
            directoryURL: accepted, maxManifestBytes: .max) else {
            Issue.record("source marker at its byte cap was not admitted")
            return
        }

        var oneByteOver = exactlyAtCap
        oneByteOver.append(0x20)
        let rejected = try Self.writeDirectory(markerData: oneByteOver)
        defer { try? FileManager.default.removeItem(at: rejected) }
        #expect {
            _ = try ModelFamilyAdmission.classify(
                directoryURL: rejected, maxManifestBytes: .max)
        } throws: { error in
            guard case ModelError.indexCorrupt = error else { return false }
            return true
        }
    }

    @Test(arguments: ["versionMajor", "versionMinor", "formatMajor", "magic", "files", "tensorRegions"])
    func rejectsUnknownOrContradictoryPackedFieldsInMarker(_ field: String) throws {
        var object = IndependentOfficialSourceFixture.markerObject()
        object[field] = [:]
        let directory = try Self.writeDirectory(
            markerData: JSONSerialization.data(withJSONObject: object, options: [.sortedKeys]))
        defer { try? FileManager.default.removeItem(at: directory) }

        #expect {
            _ = try ModelFamilyAdmission.classify(directoryURL: directory)
        } throws: { error in
            guard case ModelError.indexCorrupt = error else { return false }
            return true
        }
    }

    @Test func rejectsChangedCanonicalDigestInMarker() throws {
        var object = IndependentOfficialSourceFixture.markerObject()
        object["contentSHA256"] = String(repeating: "0", count: 64)
        let directory = try Self.writeDirectory(
            markerData: JSONSerialization.data(withJSONObject: object, options: [.sortedKeys]))
        defer { try? FileManager.default.removeItem(at: directory) }

        #expect {
            _ = try ModelFamilyAdmission.classify(directoryURL: directory)
        } throws: { error in
            guard case ModelError.indexCorrupt = error else { return false }
            return true
        }
    }

    @Test func rejectsDuplicateTopLevelMembersInBothOrdersThroughStrictDecodeAndAdmission() throws {
        let escapedEquivalentRootKey = "source" + "\\" + "u0052oot"
        let duplicates = [
            "\"sourceRoot\":\"/tmp/source-a\",\"sourceRoot\":\"/tmp/source-b\"",
            "\"sourceRoot\":\"/tmp/source-b\",\"sourceRoot\":\"/tmp/source-a\"",
            "\"sourceRoot\":\"/tmp/source-a\",\"\(escapedEquivalentRootKey)\":\"/tmp/source-b\"",
            "\"\(escapedEquivalentRootKey)\":\"/tmp/source-b\",\"sourceRoot\":\"/tmp/source-a\"",
        ]
        for members in duplicates {
            try expectStrictDecodeAndAdmissionToReject(
                IndependentOfficialSourceFixture.rawMarkerData(sourceRootMembers: members))
        }
    }

    @Test func rejectsDuplicateAndEscapedEquivalentSidecarKeysInBothOrders() throws {
        let correct = try #require(IndependentOfficialSourceFixture.sidecars["config.json"])
        let altered = String(repeating: "0", count: 64)
        let escapedEquivalentName = #"config\u002ejson"#
        let duplicateMembers = [
            "\"config.json\":\"\(correct)\",\"config.json\":\"\(altered)\"",
            "\"config.json\":\"\(altered)\",\"config.json\":\"\(correct)\"",
            "\"config.json\":\"\(correct)\",\"\(escapedEquivalentName)\":\"\(correct)\"",
            "\"\(escapedEquivalentName)\":\"\(correct)\",\"config.json\":\"\(correct)\"",
        ]
        for duplicate in duplicateMembers {
            let members = IndependentOfficialSourceFixture.sidecarMembers(
                duplicateConfigurationEntries: duplicate)
            try expectStrictDecodeAndAdmissionToReject(
                IndependentOfficialSourceFixture.rawMarkerData(sidecarMapMembers: members))
        }
    }

    @Test func rejectsDuplicateShardObjectKeysAndEscapedEquivalentKeysInBothOrders() throws {
        let shard = IndependentOfficialSourceFixture.shards[0]
        let alteredName = "altered-\(shard.filename)"
        let alteredHash = String(repeating: "0", count: 64)
        let escapedEquivalentKey = #"file\u006eame"#
        let duplicateShardObjects = [
            "{\"filename\":\"\(shard.filename)\",\"filename\":\"\(alteredName)\",\"sha256\":\"\(shard.sha256)\"}",
            "{\"filename\":\"\(alteredName)\",\"filename\":\"\(shard.filename)\",\"sha256\":\"\(shard.sha256)\"}",
            "{\"filename\":\"\(shard.filename)\",\"sha256\":\"\(shard.sha256)\",\"sha256\":\"\(alteredHash)\"}",
            "{\"filename\":\"\(shard.filename)\",\"sha256\":\"\(alteredHash)\",\"sha256\":\"\(shard.sha256)\"}",
            "{\"filename\":\"\(shard.filename)\",\"\(escapedEquivalentKey)\":\"\(shard.filename)\",\"sha256\":\"\(shard.sha256)\"}",
            "{\"\(escapedEquivalentKey)\":\"\(shard.filename)\",\"filename\":\"\(shard.filename)\",\"sha256\":\"\(shard.sha256)\"}",
        ]
        for duplicateShard in duplicateShardObjects {
            try expectStrictDecodeAndAdmissionToReject(
                IndependentOfficialSourceFixture.rawMarkerData(
                    shardArrayMembers: IndependentOfficialSourceFixture.shardArray(
                        firstShardObject: duplicateShard)))
        }
    }

    @Test func rejectsGemmaV1ManifestWithOfficialSourceMarker() throws {
        let (directory, _) = try ManifestReaderTests.writeToyManifest(
            ["quant": ManifestReaderTests.quant()], config: .gemma4_26B_A4B)
        defer { try? FileManager.default.removeItem(at: directory) }
        try IndependentOfficialSourceFixture.markerData().write(
            to: directory.appendingPathComponent(OfficialSourceDescriptor.markerFilename))

        #expect {
            _ = try ModelFamilyAdmission.classify(directoryURL: directory)
        } throws: { error in
            guard case ModelError.indexCorrupt = error else { return false }
            return true
        }
    }

    @Test func rejectsSymlinkedSourceMarkerThroughProtectedMetadataReader() throws {
        let directory = try Self.writeDirectory(markerData: nil)
        defer { try? FileManager.default.removeItem(at: directory) }
        let target = FileManager.default.temporaryDirectory
            .appendingPathComponent("official-source-marker-target-\(UUID().uuidString)")
        try IndependentOfficialSourceFixture.markerData().write(to: target)
        defer { try? FileManager.default.removeItem(at: target) }
        try FileManager.default.createSymbolicLink(
            at: directory.appendingPathComponent(OfficialSourceDescriptor.markerFilename),
            withDestinationURL: target)

        #expect {
            _ = try ModelFamilyAdmission.classify(directoryURL: directory)
        } throws: { error in
            guard case ModelError.indexCorrupt = error else { return false }
            return true
        }
    }

    private func expectStrictDecodeAndAdmissionToReject(_ data: Data) throws {
        #expect(throws: OfficialSourceDescriptorError.self) {
            try OfficialSourceDescriptor.decodeStrict(data: data)
        }
        let directory = try Self.writeDirectory(markerData: data)
        defer { try? FileManager.default.removeItem(at: directory) }
        #expect {
            _ = try ModelFamilyAdmission.classify(directoryURL: directory)
        } throws: { error in
            guard case ModelError.indexCorrupt = error else { return false }
            return true
        }
    }

    private static func writeDirectory(markerData: Data?) throws -> URL {
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("official-source-admission-\(UUID().uuidString)")
        try FileManager.default.createDirectory(
            at: directory, withIntermediateDirectories: true)
        if let markerData {
            try markerData.write(
                to: directory.appendingPathComponent(OfficialSourceDescriptor.markerFilename))
        }
        return directory
    }
}

