    static var nonexistentSourceRoot: String {
        "/tmp/official-source-root-not-created-\(UUID().uuidString)"
    }

    static func markerObject(sourceRoot: String = nonexistentSourceRoot) -> [String: Any] {
        [
            "kind": "official-safetensors-bf16-v1",
            "version": 1,
            "repository": repository,
            "revision": revision,
            "storageProfile": storageProfile,
            "sidecarSHA256": sidecars,
            "shards": shards.map { ["filename": $0.filename, "sha256": $0.sha256] },
            "sourceRoot": sourceRoot,
            "contentSHA256": expectedContentSHA256,
        ]
    }

    static func markerData(sourceRoot: String = nonexistentSourceRoot) throws -> Data {
        try JSONSerialization.data(
            withJSONObject: markerObject(sourceRoot: sourceRoot), options: [.sortedKeys])
    }

    static func rawMarkerData(
        sidecarMapMembers: String? = nil,
        shardArrayMembers: String? = nil,
        sourceRootMembers: String? = nil
    ) -> Data {
        let sidecarsJSON = sidecarMapMembers ?? sidecars.keys.sorted().map { name in
            "\"\(name)\":\"\(sidecars[name]!)\""
        }.joined(separator: ",")
        let shardsJSON = shardArrayMembers ?? shardArray()
        let rootJSON = sourceRootMembers
            ?? "\"sourceRoot\":\"\(nonexistentSourceRoot)\""
        let json = """
        {"kind":"official-safetensors-bf16-v1","version":1,
        "repository":"\(repository)","revision":"\(revision)",
        "storageProfile":"\(storageProfile)",
        "sidecarSHA256":{\(sidecarsJSON)},"shards":[\(shardsJSON)],
        \(rootJSON),"contentSHA256":"\(expectedContentSHA256)"}
        """
        return Data(json.utf8)
    }

    static func sidecarMembers(duplicateConfigurationEntries: String) -> String {
        let otherEntries = sidecars.keys.filter { $0 != "config.json" }.sorted().map { name in
            "\"\(name)\":\"\(sidecars[name]!)\""
        }
        return ([duplicateConfigurationEntries] + otherEntries).joined(separator: ",")
    }

    static func shardArray(firstShardObject: String? = nil) -> String {
        let first: String
        if let firstShardObject {
            first = firstShardObject
        } else {
            let shard = shards[0]
            first = "{\"filename\":\"\(shard.filename)\",\"sha256\":\"\(shard.sha256)\"}"
        }
        let rest = shards.dropFirst().map {
            "{\"filename\":\"\($0.filename)\",\"sha256\":\"\($0.sha256)\"}"
        }
        return ([first] + rest).joined(separator: ",")
    }
